import re

def parse_version(version_str):
    # Baştaki 'v' karakterini temizle
    if version_str.startswith('v'):
        version_str = version_str[1:]

    # Regex ile ana bileşenleri ayır: core, pre-release, build
    # SemVer regex yapısı: MAJOR.MINOR.PATCH (-pre) (+build)
    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$'
    match = re.match(pattern, version_str)

    if not match:
        raise ValueError(f"Geçersiz SemVer formatı: {version_str}")

    major_str, minor_str, patch_str, pre_release_str, build_str = match.groups()

    # Sayısal kısımların baştaki sıfır kontrolü (0 hariç)
    for s in [major_str, minor_str, patch_str]:
        if len(s) > 1 and s.startswith('0'):
            raise ValueError(f"Hatalı sayı formatı (baştaki sıfır olamaz): {s}")

    major = int(major_str)
    minor = int(minor_str)
    patch = int(patch_str)

    # Pre-release parçalarını hazırla
    pre_parts = []
    if pre_release_str:
        for part in pre_release_str.split('.'):
            if part.isdigit():
                pre_parts.append(int(part))
            else:
                pre_parts.append(part)
    else:
        # Ön sürüm yoksa, karşılaştırmada daha yüksek öncelik sağlaması için 
        # çok büyük bir nesne veya özel bir işaretleyici kullanılabilir.
        # Ancak mantıksal olarak "varlık" (existence) farkı önemlidir.
        pre_parts = None

    return (major, minor, patch, pre_parts)

def compare(a: str, b: str) -> int:
    """
        a < b ise -1, eşitse 0, a > b ise 1 döner.
    """
    parsed_a = parse_version(a)
    parsed_b = parse_version(b)

    # 1. MAJOR, MINOR, PATCH karşılaştırması
    for i in range(3):
        if parsed_a[i] > parsed_b[i]:
            return 1
        if parsed_a[i] < parsed_b[i]:
            return -1

    # 2. Pre-release karşılaştırması
    # SemVer kuralı: Pre-release olan versiyon, olmayan versiyondan daha düşüktür.
    if parsed_a[3] is None and parsed_b[3] is not None:
        return 1  # a (normal) > b (pre-release)
    if parsed_a[3] is not None and parsed_b[3] is None:
        return -1 # a (pre-release) < b (normal)

    if parsed_a[3] is not None and parsed_b[3] is not None:
        # İki pre-release var, parçaları tek tek karşılaştır
        for p_a, p_b in zip(parsed_a[3], parsed_b[3]):
            # Tip kontrolü (sayı vs string)
            # Sayısal karşılaştırma kuralı:
            # İki parça sayısal ise sayısal karşılaştırılır, değilse ASCII.
            # Bir sayı bir string ise sayısal olan daha düşüktür.

            a_is_int = isinstance(p_a, int)
            b_is_int = isinstance(p_b, int)

            if a_is_int and b_is_int:
                if p_a > p_b: return 1
                if p_a < p_b: return -1
            elif not a_is_int and not b_is_int:
                if p_a > p_b: return 1
                if p_a < p_b: return -1
            else:
                # Biri sayı biri string ise, sayı olan daha düşük önceliklidir
                return -1 if a_is_int else 1

        # Eğer tüm parçalar aynıysa, uzunluk belirler
        if len(parsed_a[3]) > len(parsed_b[3]):
            return 1
        if len(parsed_a[3]) < len(parsed_b[3]):
            return -1

    return 0

def sort_versions(versions: list[str]) -> list[str]:
    """
        Artan sıralı liste döner (Stable sort).
    """
    # Python'un sort() metodu stabildir. 
    # compare fonksiyonunu bir key'e dönüştürmemiz gerekir.

    class SortKey:
        def __init__(self, v_str):
            self.v_str = v_str
            self.parsed = parse_version(v_str)

        def __lt__(self, other):
            return compare(self.v_str, other.v_str) == -1

        def __eq__(self, other):
            return compare(self.v_str, other.v_str) == 0

    return sorted(versions, key=lambda x: SortKey(x))

